actions.script:
const marketing=ec.resource.script('component://mr-pass/screen/Marketing/Marketing.js')
const offerParam=marketing.param('offer')
const notFound=()=>{throw Object.assign(new Error('Page not found'),{moquiErrorKind:'NotFound'})}
if(!offerParam || !/^[A-Za-z0-9_-]{1,40}$/.test(offerParam))notFound()
const found=marketing.portal.attempt('getMarketingEvent',{siteId:resolvedSiteId,registrationPolicyId:offerParam})
if(found.error){
    if(found.error.kind!=='NotFound')throw Object.assign(new Error(found.error.message),{moquiErrorKind:found.error.kind})
    notFound()
}
publicEvent=found.result.event
// the description's paragraphs, each shown as text (never markup)
descriptionParagraphs=String(publicEvent.description || '').split(/\n\s*\n/).map(s=>s.trim()).filter(s=>s)
termsParagraphs=String(publicEvent.terms || '').split(/\n\s*\n/).map(s=>s.trim()).filter(s=>s)
// P17: the Register page beside this one
registerPath=String(publicPath || '').replace(/\/Event$/,'/Register')
